code:
prices_in_last_7_days = DailyPrices.WHERE(DATEDIFF("days", date, DATETIME('now')) <= 6)

acp_by_ticker_type = prices_in_last_7_days.CALCULATE(
    type=ticker.ticker_type
).PARTITION(
    name="type_groups", by=type
).CALCULATE(
    ticker_type=type,
    average_closing_price=AVG(prices_in_last_7_days.close)
)
